begin;
set local lock_timeout='5s'; set local statement_timeout='30s';
select public.nearr_paid_lock();
select id from public.nearr_plus_config where id for update;
select singleton from public.global_release_policy where singleton for share;
select environment_name from public.token_monetization_config for share;
create temporary table mapping_financial_before on commit drop as select 'place_find_wallets' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.place_find_wallets t) q union all select 'place_find_lots' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.place_find_lots t) q union all select 'place_find_ledger' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.place_find_ledger t) q union all select 'place_find_purchase_transactions' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.place_find_purchase_transactions t) q union all select 'nearr_plus_customers' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_plus_customers t) q union all select 'nearr_plus_entitlements' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_plus_entitlements t) q union all select 'nearr_plus_recognitions' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_plus_recognitions t) q union all select 'nearr_plus_webhook_events' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_plus_webhook_events t) q union all select 'nearr_paid_purchase_states' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_paid_purchase_states t) q union all select 'nearr_paid_recovery_receipts' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_paid_recovery_receipts t) q union all select 'nearr_paid_finds' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_paid_finds t) q;
do $guard$
declare written integer;
begin
  if (select count(*) from public.nearr_plus_config)<>1 or (select to_jsonb(c) from public.nearr_plus_config c where id) is distinct from '{"catalog_verified":false,"enforce_allowance":false,"entitlement_id":"nearr_plus","environment":"SANDBOX","free_finds":3,"id":true,"legacy_obligations_evidence_reference":null,"legacy_obligations_reconciled":false,"offering_id":"nearr_paid_v1","paid_find_policy_enabled":false,"plus_finds":10,"product_id":"com.nearr.plus.unlimited.monthly.v1","release_mode":"paid","release_qualified":false,"revenuecat_app_id":null,"revenuecat_project_id":null,"revenuecat_token_product_ids":{},"sales_enabled":false,"subscription_benefit":"unlimited","token_catalog_verified":false}'::jsonb then raise exception 'mapping_unexpected_config'; end if;
  if exists(select 1 from public.nearr_plus_config where sales_enabled or enforce_allowance or release_qualified or catalog_verified or token_catalog_verified or paid_find_policy_enabled or legacy_obligations_reconciled or environment<>'SANDBOX' or release_mode<>'paid') then raise exception 'mapping_activation_not_closed'; end if;
  if (select to_jsonb(p) from public.global_release_policy p where singleton) is distinct from '{"ai_notice_version":"nearr-ai-openai-v1","evidence_reference":null,"legal_approved":false,"policy_version":"nearr-global-13-v1","privacy_notice_version":"nearr-global-privacy-v1","provider_route":"disabled","purchase_qualified":false,"recognition_qualified":false,"singleton":true,"terms_version":"nearr-global-terms-v1"}'::jsonb then raise exception 'mapping_global_policy_changed'; end if;
  if exists(select 1 from public.global_release_policy where legal_approved or recognition_qualified or purchase_qualified or provider_route<>'disabled') then raise exception 'mapping_global_activation_not_closed'; end if;
  update public.nearr_plus_config set revenuecat_app_id='app7434757255',revenuecat_project_id='proj7d727ef6',revenuecat_token_product_ids='{"com.nearr.tokens.20.v2":"prodd6ac7e45d4","com.nearr.tokens.50.v2":"prodc41f2e9dd5","com.nearr.tokens.200.v2":"prod394420f4e2"}'::jsonb where id;
  get diagnostics written=row_count; if written<>1 then raise exception 'mapping_row_count'; end if;
  if (select to_jsonb(c)-array['revenuecat_app_id','revenuecat_project_id','revenuecat_token_product_ids'] from public.nearr_plus_config c where id) is distinct from '{"catalog_verified":false,"enforce_allowance":false,"entitlement_id":"nearr_plus","environment":"SANDBOX","free_finds":3,"id":true,"legacy_obligations_evidence_reference":null,"legacy_obligations_reconciled":false,"offering_id":"nearr_paid_v1","paid_find_policy_enabled":false,"plus_finds":10,"product_id":"com.nearr.plus.unlimited.monthly.v1","release_mode":"paid","release_qualified":false,"sales_enabled":false,"subscription_benefit":"unlimited","token_catalog_verified":false}'::jsonb then raise exception 'mapping_unintended_config_change'; end if;
  if exists(select * from mapping_financial_before except select * from (select 'place_find_wallets' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.place_find_wallets t) q union all select 'place_find_lots' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.place_find_lots t) q union all select 'place_find_ledger' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.place_find_ledger t) q union all select 'place_find_purchase_transactions' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.place_find_purchase_transactions t) q union all select 'nearr_plus_customers' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_plus_customers t) q union all select 'nearr_plus_entitlements' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_plus_entitlements t) q union all select 'nearr_plus_recognitions' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_plus_recognitions t) q union all select 'nearr_plus_webhook_events' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_plus_webhook_events t) q union all select 'nearr_paid_purchase_states' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_paid_purchase_states t) q union all select 'nearr_paid_recovery_receipts' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_paid_recovery_receipts t) q union all select 'nearr_paid_finds' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_paid_finds t) q) f) or exists(select * from (select 'place_find_wallets' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.place_find_wallets t) q union all select 'place_find_lots' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.place_find_lots t) q union all select 'place_find_ledger' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.place_find_ledger t) q union all select 'place_find_purchase_transactions' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.place_find_purchase_transactions t) q union all select 'nearr_plus_customers' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_plus_customers t) q union all select 'nearr_plus_entitlements' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_plus_entitlements t) q union all select 'nearr_plus_recognitions' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_plus_recognitions t) q union all select 'nearr_plus_webhook_events' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_plus_webhook_events t) q union all select 'nearr_paid_purchase_states' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_paid_purchase_states t) q union all select 'nearr_paid_recovery_receipts' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_paid_recovery_receipts t) q union all select 'nearr_paid_finds' as relation,count(*)::bigint as rows,md5(coalesce(string_agg(row_hash,'' order by row_hash),'')) as checksum from (select md5(to_jsonb(t)::text) as row_hash from public.nearr_paid_finds t) q) f except select * from mapping_financial_before) then raise exception 'mapping_changed_financial_rows'; end if;
end $guard$;
commit;
